<style>
#_ai_btn{position:fixed;bottom:24px;right:24px;z-index:9998;width:58px;height:58px;border-radius:50%;background:linear-gradient(135deg,#5b5ce2,#7c3aed);box-shadow:0 4px 24px rgba(91,92,226,.55);border:none;cursor:pointer;display:flex;align-items:center;justify-content:center;transition:transform .2s,box-shadow .2s}
#_ai_btn:hover{transform:scale(1.09);box-shadow:0 6px 32px rgba(91,92,226,.75)}
#_ai_btn svg{width:28px;height:28px;fill:#fff}
#_ai_badge{position:absolute;top:-3px;right:-3px;background:#ef4444;color:#fff;font-size:10px;font-weight:700;border-radius:50%;width:18px;height:18px;display:none;align-items:center;justify-content:center;line-height:1}
#_ai_chat{position:fixed;bottom:92px;right:24px;z-index:9999;width:360px;max-width:calc(100vw - 32px);background:#10101a;border:1px solid #1e1e2e;border-radius:18px;box-shadow:0 12px 48px rgba(0,0,0,.65);display:none;flex-direction:column;overflow:hidden;font-family:'Inter',sans-serif;animation:_aiSlide .25s ease}
@keyframes _aiSlide{from{opacity:0;transform:translateY(18px)}to{opacity:1;transform:translateY(0)}}
#_ai_header{background:linear-gradient(135deg,#5b5ce2,#7c3aed);padding:14px 16px;display:flex;align-items:center;gap:10px}
._ai_av{width:36px;height:36px;border-radius:50%;background:rgba(255,255,255,.2);display:flex;align-items:center;justify-content:center;flex-shrink:0}
._ai_av svg{width:20px;height:20px;fill:#fff}
._ai_hi h4{color:#fff;font-size:.9rem;font-weight:700;margin:0;line-height:1.2}
._ai_hi p{color:rgba(255,255,255,.75);font-size:.72rem;margin:0}
._ai_dot{width:8px;height:8px;background:#22c55e;border-radius:50%;display:inline-block;margin-right:4px}
#_ai_close{margin-left:auto;background:none;border:none;cursor:pointer;color:rgba(255,255,255,.8);font-size:1.2rem;line-height:1;padding:2px 6px}
#_ai_close:hover{color:#fff}
#_ai_msgs{flex:1;overflow-y:auto;padding:14px 14px 8px;display:flex;flex-direction:column;gap:10px;max-height:340px;min-height:160px;scrollbar-width:thin;scrollbar-color:#2a2a3e transparent}
#_ai_msgs::-webkit-scrollbar{width:4px}
#_ai_msgs::-webkit-scrollbar-thumb{background:#2a2a3e;border-radius:4px}
._ai_msg{display:flex;gap:8px;align-items:flex-end}
._ai_msg.bot{justify-content:flex-start}
._ai_msg.usr{justify-content:flex-end}
._ai_bub{max-width:80%;padding:9px 13px;border-radius:14px;font-size:.82rem;line-height:1.5;word-break:break-word}
._ai_msg.bot ._ai_bub{background:#1a1a2e;color:#e0e0f0;border-bottom-left-radius:4px}
._ai_msg.usr ._ai_bub{background:#5b5ce2;color:#fff;border-bottom-right-radius:4px}
._ai_ico{width:26px;height:26px;border-radius:50%;background:#1a1a2e;flex-shrink:0;display:flex;align-items:center;justify-content:center;margin-bottom:2px}
._ai_ico svg{width:14px;height:14px;fill:#5b5ce2}
._ai_typing ._ai_bub{background:#1a1a2e;padding:12px 16px}
._ai_dots{display:flex;gap:4px;align-items:center}
._ai_dots span{width:7px;height:7px;border-radius:50%;background:#8888aa;animation:_aiBounce 1.2s ease-in-out infinite}
._ai_dots span:nth-child(2){animation-delay:.2s}
._ai_dots span:nth-child(3){animation-delay:.4s}
@keyframes _aiBounce{0%,60%,100%{transform:translateY(0)}30%{transform:translateY(-6px)}}
#_ai_qr{padding:6px 14px 4px;display:flex;gap:6px;flex-wrap:wrap}
._ai_q{background:#1a1a2e;border:1px solid #2e2e48;color:#a0a0c0;font-size:.72rem;padding:5px 10px;border-radius:20px;cursor:pointer;transition:.15s;white-space:nowrap}
._ai_q:hover{background:#5b5ce2;color:#fff;border-color:#5b5ce2}
#_ai_ia{display:flex;align-items:flex-end;gap:8px;padding:10px 12px 12px;border-top:1px solid #1e1e2e}
#_ai_inp{flex:1;background:#1a1a2e;border:1px solid #2e2e48;color:#e0e0f0;border-radius:12px;padding:9px 12px;font-size:.83rem;resize:none;outline:none;line-height:1.4;max-height:90px;min-height:38px;font-family:inherit;transition:border-color .2s}
#_ai_inp::placeholder{color:#555570}
#_ai_inp:focus{border-color:#5b5ce2}
#_ai_send{background:#5b5ce2;border:none;border-radius:10px;cursor:pointer;width:38px;height:38px;flex-shrink:0;display:flex;align-items:center;justify-content:center;transition:background .2s,transform .1s}
#_ai_send:hover{background:#4a4bc7}
#_ai_send:active{transform:scale(.93)}
#_ai_send svg{width:16px;height:16px;fill:#fff}
#_ai_send:disabled{background:#2e2e48;cursor:not-allowed}
</style>
<button id=\"_ai_btn\" aria-label=\"AI Support\">
  <svg viewBox=\"0 0 24 24\"><path d=\"M12 2C6.48 2 2 6.03 2 11c0 2.7 1.23 5.11 3.18 6.79L4 22l4.44-1.48C9.55 20.83 10.75 21 12 21c5.52 0 10-4.03 10-9S17.52 2 12 2zm1 13H7v-2h6v2zm4-4H7V9h10v2z\"/></svg>
  <span id=\"_ai_badge\">1</span>
</button>
<div id=\"_ai_chat\">
  <div id=\"_ai_header\">
    <div class=\"_ai_av\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 2C6.48 2 2 6.03 2 11c0 2.7 1.23 5.11 3.18 6.79L4 22l4.44-1.48C9.55 20.83 10.75 21 12 21c5.52 0 10-4.03 10-9S17.52 2 12 2z\"/></svg></div>
    <div class=\"_ai_hi\"><h4>CDVRS AI</h4><p><span class=\"_ai_dot\"></span>En ligne — répond instantanément</p></div>
    <button id=\"_ai_close\">&#x2715;</button>
  </div>
  <div id=\"_ai_msgs\">
    <div class=\"_ai_msg bot\" id=\"_ai_welcome\">
      <div class=\"_ai_ico\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 2C6.48 2 2 6.03 2 11c0 2.7 1.23 5.11 3.18 6.79L4 22l4.44-1.48C9.55 20.83 10.75 21 12 21c5.52 0 10-4.03 10-9S17.52 2 12 2z\"/></svg></div>
      <div class=\"_ai_bub\" id=\"_ai_greet\">👋 Bonjour ! Je suis l'assistant IA de <strong>CDVRS</strong>.<br>Je peux vous aider avec vos <strong>commandes</strong>, <strong>dépôts</strong>, <strong>services SMM</strong> et <strong>votre compte</strong>.</div>
    </div>
  </div>
  <div id=\"_ai_qr\">
    <button class=\"_ai_q\" data-m=\"Quel est le statut de ma commande ?\">📦 Ma commande</button>
    <button class=\"_ai_q\" data-m=\"Comment recharger mon solde ?\">💳 Recharger</button>
    <button class=\"_ai_q\" data-m=\"Quels services sont disponibles ?\">⭐ Services</button>
    <button class=\"_ai_q\" data-m=\"Je voudrais un remboursement\">🔄 Remboursement</button>
  </div>
  <div id=\"_ai_ia\">
    <textarea id=\"_ai_inp\" placeholder=\"Posez votre question…\" rows=\"1\" maxlength=\"800\"></textarea>
    <button id=\"_ai_send\"><svg viewBox=\"0 0 24 24\"><path d=\"M2.01 21L23 12 2.01 3 2 10l15 2-15 2z\"/></svg></button>
  </div>
</div>
<script>
(function(){
  var btn=document.getElementById('_ai_btn'),chat=document.getElementById('_ai_chat'),
      msgs=document.getElementById('_ai_msgs'),inp=document.getElementById('_ai_inp'),
      snd=document.getElementById('_ai_send'),badge=document.getElementById('_ai_badge'),
      cls=document.getElementById('_ai_close'),hist=[],open=false;
  setTimeout(function(){if(!open)badge.style.display='flex';},3500);
  function toggle(){open=!open;chat.style.display=open?'flex':'none';if(open){badge.style.display='none';inp.focus();scroll();}}
  btn.addEventListener('click',toggle);cls.addEventListener('click',toggle);
  document.querySelectorAll('._ai_q').forEach(function(q){
    q.addEventListener('click',function(){if(!open)toggle();send(q.dataset.m);});
  });
  inp.addEventListener('input',function(){inp.style.height='auto';inp.style.height=Math.min(inp.scrollHeight,90)+'px';});
  inp.addEventListener('keydown',function(e){if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();go();}});
  snd.addEventListener('click',go);
  function go(){var t=inp.value.trim();if(!t||snd.disabled)return;send(t);inp.value='';inp.style.height='auto';}
  function scroll(){requestAnimationFrame(function(){msgs.scrollTop=msgs.scrollHeight;});}
  function esc(s){return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\"/g,'&quot;');}
  function addMsg(role,text){
    var w=document.createElement('div');w.className='_ai_msg '+(role==='bot'?'bot':'usr');
    if(role==='bot')w.innerHTML='<div class=\"_ai_ico\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 2C6.48 2 2 6.03 2 11c0 2.7 1.23 5.11 3.18 6.79L4 22l4.44-1.48C9.55 20.83 10.75 21 12 21c5.52 0 10-4.03 10-9S17.52 2 12 2z\"/></svg></div><div class=\"_ai_bub\">'+esc(text).replace(/\\n/g,'<br>')+'</div>';
    else w.innerHTML='<div class=\"_ai_bub\">'+esc(text).replace(/\\n/g,'<br>')+'</div>';
    msgs.appendChild(w);scroll();return w;
  }
  function typing(){
    var w=document.createElement('div');w.className='_ai_msg bot _ai_typing';
    w.innerHTML='<div class=\"_ai_ico\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 2C6.48 2 2 6.03 2 11c0 2.7 1.23 5.11 3.18 6.79L4 22l4.44-1.48C9.55 20.83 10.75 21 12 21c5.52 0 10-4.03 10-9S17.52 2 12 2z\"/></svg></div><div class=\"_ai_bub\"><div class=\"_ai_dots\"><span></span><span></span><span></span></div></div>';
    msgs.appendChild(w);scroll();return w;
  }
  function send(text){
    addMsg('usr',text);snd.disabled=true;
    var t=typing();hist.push({role:'user',content:text});
    fetch('/api/ai-support.php',{method:'POST',headers:{'Content-Type':'application/json'},
      body:JSON.stringify({message:text,history:hist.slice(-10)})})
    .then(function(r){return r.json();})
    .then(function(d){t.remove();var r=d.reply||'Une erreur est survenue.';addMsg('bot',r);hist.push({role:'assistant',content:r});})
    .catch(function(){t.remove();addMsg('bot','Erreur réseau. Veuillez réessayer.');})
    .finally(function(){snd.disabled=false;inp.focus();});
  }
})();
</script>
<script>
(function(){
  var name='';
  try{
    // Cheap Panel: try common username selectors
    var sel=['.client_name','.user-name','.username','[data-username]','.nav-user','#user_name','.header-username','.topbar-user'];
    for(var i=0;i<sel.length;i++){var el=document.querySelector(sel[i]);if(el&&el.textContent.trim()){name=el.textContent.trim();break;}}
    if(!name&&window.modules&&window.modules.layouts&&window.modules.layouts.username)name=window.modules.layouts.username;
    
  }catch(e){}
  if(name){
    var g=document.getElementById('_ai_greet');
    if(g)g.innerHTML='' + ' <strong>'+name+'</strong>! 👋' + (g.innerHTML.split('👋')[1]||'');
  }
})();
</script>

